\label{lem:inner-products} \cite{yang2026second}
For \(z_h,w_h\in V_h\) with coefficient matrices
\(Z,W\in\mathbb{R}^{m\times n}\), the mass-lumped inner products satisfy
\begin{align}
  (z_h,w_h)_h
  &=
  (Z,W)_M,
  \label{eq:ip-mass}
  \\
  (\nabla z_h,\nabla w_h)_h
  &=
  -(L_xZ+ZL_y^\top,W)_M,
  \label{eq:ip-stiff}
\end{align}
where the matrices
\begin{equation}
  L_x=-M_x^{-1}A_x,
  \qquad
  L_y=-M_y^{-1}A_y.
  \label{eq:1d-diffusion-operators}
\end{equation}

\label{lem:wellposed_full_rank}
For any $\Delta t>0$, let $w_h^\mathfrak{n}\in V_h$ be given. The FR-MLFEM scheme \eqref{eq:fd_weak_dr} admits a unique solution $w_h^{\mathfrak{n}+1}\in V_h$. Moreover, the solution satisfies the $L^2$-stability estimate
\begin{equation}
\label{eq:L2_stability_full_rank}
\|w_h^{\mathfrak{n}+1}\|_{h}
\leq
\|w_h^\mathfrak{n}\|_{h}.
\end{equation}

\label{def:weighted_dlra}
The WDLRA of the matrix differential equation \eqref{eq:matODE} is defined as the rank-$r$ matrix
$\mathcal{Z}(t) \in \mathcal{M}_r$ satisfying
\begin{equation}\label{eq:weighted_dlra_dr}
\partial_t \mathcal{Z}
=
\underset{\delta Z \in T_{\mathcal{Z}}\mathcal{M}_r}{\arg\min}
\,
\|\delta Z-\mathscr{L}(\mathcal{Z})\|_M,
\end{equation}
with initial condition
\(
\mathcal{Z}(0)=\mathcal{Z}_0\in\mathcal{M}_r,
\)
where $T_{\mathcal{Z}}\mathcal{M}_r$ denotes the tangent space of $\mathcal{M}_r$ at $\mathcal{Z}$.

\label{lem:mateqfem}
The matrices $K^{\mathfrak{n}+1}$, $L^{\mathfrak{n}+1}$, and
$S^{\mathfrak{n}+1}$ solve \eqref{eq:k_eqn}, \eqref{eq:l_eqn}, and
\eqref{eq:s_eqn} in \Cref{alg:KLS-Steps}, respectively, if and only if the 
functions
\begin{align*}
w_K^{\mathfrak{n}+1}
&:= \Phi(x)^\top K^{\mathfrak{n}+1}
(V^\mathfrak{n})^\top \Psi(y) \in V_1^\mathfrak{n},\\
w_L^{\mathfrak{n}+1}
&:= \Phi(x)^\top U^\mathfrak{n}
(L^{\mathfrak{n}+1})^\top \Psi(y) \in V_2^\mathfrak{n},\\
w_S^{\mathfrak{n}+1}
&:= \Phi(x)^\top U^{\mathfrak{n}+1} S^{\mathfrak{n}+1}
(V^{\mathfrak{n}+1})^\top \Psi(y) \in V_0^{\mathfrak{n}+1}
\end{align*}
solve the following first-order implicit BUG-MLFEM scheme:
\begin{align}
  (D_t w_K^{\mathfrak{n}+1}, w_1)_h
  + (\nabla w_K^{\mathfrak{n}+1}, \nabla w_1)_h
  - \alpha (w_K^{\mathfrak{n}+1}, w_1)_h &= 0,
  &&\forall w_1 \in V_1^{\mathfrak{n}}, \label{eq:Kvar32}\\
  (D_t w_L^{\mathfrak{n}+1}, w_2)_h
  + (\nabla w_L^{\mathfrak{n}+1}, \nabla w_2)_h
  - \alpha (w_L^{\mathfrak{n}+1}, w_2)_h &= 0,
  &&\forall w_2 \in V_2^{\mathfrak{n}}, \label{eq:Lvar32}\\
  (D_t w_S^{\mathfrak{n}+1}, w_0)_h
  + (\nabla w_S^{\mathfrak{n}+1}, \nabla w_0)_h
  - \alpha (w_S^{\mathfrak{n}+1}, w_0)_h &= 0,
  &&\forall w_0 \in V_0^{\mathfrak{n}+1}, \label{eq:Svar32}
\end{align}
where $w_K^\mathfrak{n} = w_L^\mathfrak{n} = w_S^\mathfrak{n} = \hat w_h^\mathfrak{n}$.

\label{thm:wp32}
Given the BUG-MLFEM solution $\hat w_h^{\mathfrak{n}}$, with
\(
w_K^{\mathfrak{n}}
=
w_L^{\mathfrak{n}}
=
w_S^{\mathfrak{n}}
=
\hat w_h^{\mathfrak{n}}.
\)
Then, (i) for any $\Delta t>0$, the first-order implicit BUG-MLFEM scheme
\eqref{eq:Kvar32}--\eqref{eq:Svar32} admits a unique solution
\begin{equation}\label{wkls}
    (w_K^{\mathfrak{n}+1},\,w_L^{\mathfrak{n}+1},\,w_S^{\mathfrak{n}+1})
\in
V_1^{\mathfrak{n}}
\times
V_2^{\mathfrak{n}}
\times
V_0^{\mathfrak{n}+1}.
\end{equation}
Equivalently, the matrix system in \Cref{alg:KLS-Steps} admits a unique
solution
\begin{equation}
(K^{\mathfrak{n}+1},\,L^{\mathfrak{n}+1},\,S^{\mathfrak{n}+1}) \in \mathbb{R}^{m\times r}\times \mathbb{R}^{n\times r}\times \mathbb{R}^{r\times r}.
\end{equation}
(ii) The BUG-MLFEM solution satisfies the mass-lumped
$L^2$-stability
\begin{equation}\label{l2stab}
\|\hat w_h^{\mathfrak{n}+1}\|_h
\leq
\|\hat w_h^{\mathfrak{n}}\|_h. 
\end{equation}

\label{Ajnons}
For each $j=1,\ldots,r$,
\begin{enumerate}
    \par\hangindent 40\p@[(i)] the matrices $\widehat{A}_j$ and
    $\widehat{A}_j+\widehat{U}\widehat{V}^{\top}$ in
    \eqref{eq:shifted-periodic-decomp} are nonsingular;
    \par\hangindent 40\p@[(ii)] the matrix
    \(
    I_2+\widehat{V}^{\top}\widehat{A}_j^{-1}\widehat{U} \in \mathbb{R}^{2\times2}
\)
    is nonsingular.
\end{enumerate}

\label{lem:smw}
For matrix $\widehat{A}_j+\widehat{U}\widehat{V}^{\top}$ in \eqref{eq:shifted-periodic-decomp},  it holds the Sherman--Morrison--Woodbury \cite{woodbury1950inverting} identity,
\begin{equation}
    \left(
        \widehat{A}_j+\widehat{U}\widehat{V}^{\top}
    \right)^{-1}
    =
    \widehat{A}_j^{-1}
    -
    \widehat{A}_j^{-1}\widehat{U}
    \left(
        I_2+\widehat{V}^{\top}\widehat{A}_j^{-1}\widehat{U}
    \right)^{-1}
    \widehat{V}^{\top}\widehat{A}_j^{-1}.
    \label{eq:woodbury-identity}
\end{equation}
